import{_ as a,c as e,o as r,ag as o}from"./chunks/framework._xRlcm3f.js";const b=JSON.parse('{"title":"图床设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/picbed.md","filePath":"guide/picbed.md","lastUpdated":1790228279000}'),d={name:"guide/picbed.md"};function i(l,t,h,s,c,n){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="图床设置" tabindex="-1">图床设置 <a class="header-anchor" href="#图床设置" aria-label="Permalink to &quot;图床设置&quot;">​</a></h1><p>图片先上传到图床，再把链接写进文章——这样平台侧拿到的是稳定可访问的图片地址。</p><h2 id="三种方式" tabindex="-1">三种方式 <a class="header-anchor" href="#三种方式" aria-label="Permalink to &quot;三种方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>适合</th></tr></thead><tbody><tr><td><strong>平台原生直传</strong></td><td>交给平台自己的图片服务处理</td><td>知乎、CSDN、微信公众号等强制使用自家服务的平台</td></tr><tr><td><strong>内置图床</strong></td><td>阿里云 OSS、腾讯云 COS 等，在插件里直接填密钥</td><td>有自己的对象存储，想统一管理图片</td></tr><tr><td><strong>PicGo</strong></td><td>连接本机运行的 PicGo 服务</td><td>已经用 PicGo 管理图床，或需要它的多图床能力</td></tr></tbody></table><h2 id="配置位置" tabindex="-1">配置位置 <a class="header-anchor" href="#配置位置" aria-label="Permalink to &quot;配置位置&quot;">​</a></h2><p>设置 → <strong>图床设置</strong>。也可以在「偏好设置」里指定<strong>默认图床</strong>，各平台可单独覆盖。</p><h2 id="平台原生直传的适用范围" tabindex="-1">平台原生直传的适用范围 <a class="header-anchor" href="#平台原生直传的适用范围" aria-label="Permalink to &quot;平台原生直传的适用范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>图片处理</th></tr></thead><tbody><tr><td>知乎、CSDN、微信公众号</td><td>使用平台自带上传，外链不被接受</td></tr><tr><td>Notion、语雀、掘金</td><td>需要配置图床</td></tr><tr><td>GitHub 系、GitLab 系（Hexo 等）</td><td>需要配置图床</td></tr><tr><td>MetaWeblog 系（博客园、Typecho、WordPress）</td><td>两者都支持；配了图床则优先用图床</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">想强制用平台自带上传</p><p>卸载图床插件即可。反过来，想强制使用自己的图床，就卸载平台侧的图床插件。</p></div><h2 id="picgo" tabindex="-1">PicGo <a class="header-anchor" href="#picgo" aria-label="Permalink to &quot;PicGo&quot;">​</a></h2><p>使用 PicGo 需要本机已安装并运行 PicGo 服务（默认端口 <code>36677</code>）。</p><ol><li>安装并启动 <a href="https://github.com/Molunerfinn/PicGo" target="_blank" rel="noreferrer">PicGo</a>。</li><li>在 PicGo 里配好至少一个图床。</li><li>回到插件的「图床设置」，选择「PicGo 强烈推荐」，确认端口与密钥。</li></ol><div class="tip custom-block"><p class="custom-block-title">挂件与扩展模式</p><p>PicGo 是本机服务，只有在插件能访问本机网络时才可用。浏览器扩展与网页版受同源策略限制，建议改用内置图床或平台原生直传。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="图床配置不生效" tabindex="-1">图床配置不生效 <a class="header-anchor" href="#图床配置不生效" aria-label="Permalink to &quot;图床配置不生效&quot;">​</a></h3><p>确认图床服务正在运行，并检查端口与密钥是否正确。发布时如果平台侧图片是本地路径，说明图床没有生效，多半是密钥或存储桶权限问题。</p><h3 id="图片上传成功但文章里显示不出来" tabindex="-1">图片上传成功但文章里显示不出来 <a class="header-anchor" href="#图片上传成功但文章里显示不出来" aria-label="Permalink to &quot;图片上传成功但文章里显示不出来&quot;">​</a></h3><p>对象存储的<strong>读权限</strong>没开。多数对象存储默认私有读写，需要把读权限设为公共读，或配置 CDN 域名。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>各平台的图床要求：<a href="/siyuan-plugin-publisher/platforms/">平台支持</a></li><li>其他问题：<a href="./faq.html">常见问题</a></li></ul>',20)])])}const u=a(d,[["render",i]]);export{b as __pageData,u as default};
